import{c as s,$ as o,Q as i,j as n,g as a,o as r,n as l,m as d}from"./chunks/framework.Ce_49mA8.js";const c="/img/en/front/personal_dashboard.webp",w=JSON.parse('{"title":"Capital Dashboard","description":"Practical guide to the consolidated capital dashboard, total net worth structure, and balance delta living expense tracking in OmniCraft ERP.","frontmatter":{"title":"Capital Dashboard","description":"Practical guide to the consolidated capital dashboard, total net worth structure, and balance delta living expense tracking in OmniCraft ERP.","datePublished":"2026-10-28","dateModified":"2026-11-16","order":19},"headers":[],"relativePath":"docs/spaces/moy-kapital/dashboard.md","filePath":"docs/spaces/moy-kapital/dashboard.md","lastUpdated":1794787200000}'),p={name:"docs/spaces/moy-kapital/dashboard.md"},u={id:"capital-dashboard-consolidated-wealth-command-center",tabindex:"-1"};function h(m,t,g,f,v,y){const e=o("DocIcon");return i(),n("div",null,[a("h1",u,[r(e,{name:"capital"}),t[0]||(t[0]=l(" Capital Dashboard: Consolidated Wealth Command Center ",-1)),t[1]||(t[1]=a("a",{class:"header-anchor",href:"#capital-dashboard-consolidated-wealth-command-center","aria-label":'Permalink to "Capital Dashboard: Consolidated Wealth Command Center"'},"​",-1))]),t[2]||(t[2]=d('<p>The <strong>Capital Dashboard</strong> tab serves as the primary executive bridge in the &quot;My Capital&quot; workspace. It executes end-to-end consolidation across isolated database files from every manufacturing workshop, service studio, and personal financial account, delivering a crystal-clear operational answer to the artisan&#39;s foundational question: <strong>what is the true combined market value of your craft business and personal assets right now</strong>.</p><p>The dashboard unifies dispersed financial streams into a unified coordinate system, dismantling classic accounting illusions: the mistaken sense of poverty during substantial investments in raw materials or machinery, or the illusion of sudden riches when customer order retainers accumulate temporarily in your bank account.</p><div class="craft-window-frame"><img src="'+c+'" alt="Consolidated Capital Dashboard in OmniCraft ERP" class="doc-image zoomable-img"></div><hr><h2 id="four-pillars-of-consolidated-net-worth" tabindex="-1">Four Pillars of Consolidated Net Worth <a class="header-anchor" href="#four-pillars-of-consolidated-net-worth" aria-label="Permalink to &quot;Four Pillars of Consolidated Net Worth&quot;">​</a></h2><p>Total wealth in OmniCraft ERP rests upon four fundamental asset pillars. Each fulfills a distinct strategic purpose in capital management:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"></span><div><strong>Accounts &amp; Wallets (Cash):</strong><br> Liquid reserves across cards, deposits, vaults, and digital wallets. </div></li><li><span class="craft-list-bullet"></span><div><strong>Investment Portfolio:</strong><br> Market valuation of securities, crypto, loans, and business stakes. </div></li><li><span class="craft-list-bullet"></span><div><strong>Personal Assets:</strong><br> Long-term property (real estate, vehicles, and personal valuables). </div></li><li><span class="craft-list-bullet"></span><div><strong>Workspace Property:</strong><br> Net equity across all active workshops, creative studios, and service facilities. </div></li></ul><h3 id="_1-accounts-and-wallets-liquid-reserve" tabindex="-1">1. Accounts and Wallets (Liquid Reserve) <a class="header-anchor" href="#_1-accounts-and-wallets-liquid-reserve" aria-label="Permalink to &quot;1. Accounts and Wallets (Liquid Reserve)&quot;">​</a></h3><p>Encompasses readily available liquidity across debit cards, checking accounts, high-yield savings deposits, and physical cash reserves. For accounts denominated in foreign currencies or digital assets, the system dynamically translates balances into your primary reporting currency using active exchange rates.</p><h3 id="_2-investment-portfolio-growth-capital" tabindex="-1">2. Investment Portfolio (Growth Capital) <a class="header-anchor" href="#_2-investment-portfolio-growth-capital" aria-label="Permalink to &quot;2. Investment Portfolio (Growth Capital)&quot;">​</a></h3><p>Reflects the cumulative current market valuation of external financial instruments: public equities, fixed-income bonds, mutual funds, digital reserves, equity stakes in partner enterprises, and interest-bearing loans issued to counterparties.</p><h3 id="_3-personal-assets-tangible-foundation" tabindex="-1">3. Personal Assets (Tangible Foundation) <a class="header-anchor" href="#_3-personal-assets-tangible-foundation" aria-label="Permalink to &quot;3. Personal Assets (Tangible Foundation)&quot;">​</a></h3><p>Captures tangible property owned outside commercial enterprise operations: residential real estate, land parcels, personal vehicles, and family valuables. Valuations respect individual ownership quotas, preventing balance sheet inflation from co-owned properties.</p><h3 id="_4-workspace-property-industrial-capital" tabindex="-1">4. Workspace Property (Industrial Capital) <a class="header-anchor" href="#_4-workspace-property-industrial-capital" aria-label="Permalink to &quot;4. Workspace Property (Industrial Capital)&quot;">​</a></h3><p>Aggregates the physical and operational book value of all registered workshops and studios:</p><ul><li><strong>Workspace Operational Cash:</strong> actual cash register balances tracked in the workspace Cash Flow (DDS) ledger;</li><li><strong>Raw Materials Inventory:</strong> aggregate valuation of leather, lumber, metal, and consumable supplies calculated via <strong>Moving Average Cost (MAC)</strong>;</li><li><strong>Finished Goods and Workbench:</strong> manufacturing cost of completed stock evaluated via <strong>First-In, First-Out (FIFO)</strong>, plus direct accumulated material costs in open work-in-progress batches;</li><li><strong>Machinery and Equipment:</strong> depreciated book value of production tools and machinery accounting for straight-line wear and tear and allocated workspace ownership shares.</li></ul><hr><h2 id="net-worth-mathematical-calculation" tabindex="-1">Net Worth Mathematical Calculation <a class="header-anchor" href="#net-worth-mathematical-calculation" aria-label="Permalink to &quot;Net Worth Mathematical Calculation&quot;">​</a></h2><p>The primary <strong>Total Net Worth</strong> card sits at the top of the workspace. Its valuation is computed by summing the four asset pillars according to a rigorous accounting rule:</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Balance Sheet</span><div class="formula-heading">Consolidated Net Worth Evaluation</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Total Net Worth</span><span class="math-op">=</span><span class="math-var">Liquid Accounts</span><span class="math-op">+</span><span class="math-var">Investments</span><span class="math-op">+</span><span class="math-var">Personal Assets</span><span class="math-op">+</span><span class="math-var">Workspace Equity</span></div></div><div class="formula-card-bottom"><p>Workspace net equity evaluates dynamically: the engine queries SQLite databases across all active commercial spaces in real time, summing cash registers, raw material reserves, finished goods valuation, and depreciated machinery shares.</p></div></div><div class="info custom-block"><p class="custom-block-title">Seamless Multi-Workspace Consolidation</p><p>If you operate a custom leathercraft workshop, a digital pattern store, and a sharpening service studio simultaneously, the dashboard automatically scans each independent SQLite database. There is no need to switch between profiles manually or calculate totals on scrap paper: data aggregates seamlessly upon opening the tab.</p></div><hr><h2 id="cash-flow-analysis-four-flow-indicators" tabindex="-1">Cash Flow Analysis: Four Flow Indicators <a class="header-anchor" href="#cash-flow-analysis-four-flow-indicators" aria-label="Permalink to &quot;Cash Flow Analysis: Four Flow Indicators&quot;">​</a></h2><p>The lower screen quadrant houses the income and expenditure diagnostic board. It compares productive output against real changes in personal net worth:</p><table class="craft-matrix-table"><thead><tr><th style="width:25%;">Earned in businesses</th><th style="width:25%;">Outside income / Saved</th><th style="width:25%;">Investment Profit</th><th style="width:25%;">Untracked living expenses</th></tr></thead><tbody><tr><td><strong>$145,000.00</strong></td><td><strong>$32,000.00</strong></td><td><strong style="color:#10b981;">+$18,540.00</strong></td><td><strong>$68,000.00</strong></td></tr></tbody></table><ol><li><strong>&quot;Earned in businesses&quot;:</strong> cumulative operational net profit across all workshops throughout their lifecycle (gross sales revenue minus raw materials cost, rent, utilities, consumables, and machinery depreciation);</li><li><strong>&quot;Outside income / Saved&quot;:</strong> total recorded personal revenue logged in the Personal Operations tab (external consulting retainers, guest lectures, sales of private items);</li><li><strong>&quot;Investment Profit&quot;:</strong> cumulative net yield across the entire investment portfolio. Combines unrealized mark-to-market valuation on open positions with net realized profits from settled trades. Highlighted with an emerald <code>+</code> prefix for capital appreciation or crimson <code>-</code> for drawdowns;</li><li><strong>&quot;Untracked living expenses&quot;:</strong> family living costs and discretionary household burn, calculated automatically through balance sheet delta analysis without manual receipt collection.</li></ol><hr><h2 id="living-expenses-via-balance-delta-mathematics" tabindex="-1">Living Expenses via Balance Delta Mathematics <a class="header-anchor" href="#living-expenses-via-balance-delta-mathematics" aria-label="Permalink to &quot;Living Expenses via Balance Delta Mathematics&quot;">​</a></h2><p>A defining engineering innovation in OmniCraft ERP is liberating the craftsman from domestic receipt tracking. The platform evaluates household living burn via the net worth balance delta:</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Balance Delta</span><div class="formula-heading">Automated Calculation of Family Living Expenses</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Living Expenses</span><span class="math-op">=</span><span class="math-var">Total Earning Pool</span><span class="math-op">−</span><span class="math-group">(</span><span class="math-var">Major Personal Outflows</span><span class="math-op">+</span><span class="math-var">Net Worth Delta</span><span class="math-group">)</span></div></div><div class="formula-card-bottom"><p>Total Earning Pool = Workshop Profits + Outside Incomes + Net Investment Returns. If consolidated capital appreciated by less than the total earned over a period, the difference represents natural household living costs for groceries, transportation, home maintenance, and routine living.</p></div></div><p><strong>Practical Calculation Example:</strong></p><ul><li>During the fiscal period, the workshop delivered net operational earnings of <strong>$30,000</strong>;</li><li>Outside design consulting yielded <strong>$5,000</strong>;</li><li>The investment portfolio produced net returns of <strong>$2,000</strong>;</li><li><em>Total Earning Pool equals $37,000</em>;</li><li>A major dental procedure was logged in the operations ledger — <strong>$7,000</strong>;</li><li>Actual liquid and physical capital across accounts and workshops increased by <strong>$18,000</strong>.</li></ul><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Numerical Example</span><div class="formula-heading">Household Living Cost Calculation</div></div><div class="formula-equation-box"><div class="math-line"><span class="math-var">Living Expenses</span><span class="math-op">=</span><span class="math-calc-expr">$37,000 − ($7,000 + $18,000) = <strong>$12,000</strong></span></div></div><div class="formula-card-bottom"><p>The engine accurately concludes that $12,000 went toward routine family living expenses without collecting a single receipt.</p></div></div><p>The software accurately concludes: $12,000 went toward routine family living expenses. The artisan was spared from cataloging a single grocery receipt or fuel voucher.</p><hr><h2 id="historical-continuity-snapshots-of-archived-workspaces" tabindex="-1">Historical Continuity: Snapshots of Archived Workspaces <a class="header-anchor" href="#historical-continuity-snapshots-of-archived-workspaces" aria-label="Permalink to &quot;Historical Continuity: Snapshots of Archived Workspaces&quot;">​</a></h2><p>In operational reality, craft workshops may reorganize legal structures, wind down, consolidate, or sell to third parties as turnkey operations.</p><p>If removing a legacy workspace purged associated financial metrics, the craftsman&#39;s historical wealth trajectory would suffer artificial collapse, indicating a fictitious drawdown.</p><p>To maintain integrity, OmniCraft ERP employs <strong>immutable historical snapshots</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Workspace Removal] ➔ [Financial Snapshot Generation] ➔ [Continuity Archive]</span></span></code></pre></div><ol><li><strong>Immutable Net Profit Lock:</strong> upon workspace removal, the system captures net performance metrics (cumulative earnings and equity standing at termination) into an internal snapshot repository;</li><li><strong>Continuity Indicator:</strong> an informational banner appears beneath the primary Net Worth card:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Scroll Icon] Snapshots of deleted spaces: 2 | Capital history preserved</span></span></code></pre></div></li><li><strong>Long-Term Analytic Fidelity:</strong> multi-year net worth trajectory charts retain historical contributions from former enterprises, safeguarding the master&#39;s authentic financial chronicle.</li></ol><hr><h2 id="indicator-reference-table" tabindex="-1">Indicator Reference Table <a class="header-anchor" href="#indicator-reference-table" aria-label="Permalink to &quot;Indicator Reference Table&quot;">​</a></h2><p>This table outlines calculation methodologies and database origins for each dashboard metric:</p><table tabindex="0"><thead><tr><th style="text-align:left;">UI Indicator</th><th style="text-align:left;">Database Source</th><th style="text-align:left;">Aggregation Methodology</th><th style="text-align:left;">Economic Definition</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>&quot;Total Net Worth&quot;</strong></td><td style="text-align:left;"><code>accounts</code>, <code>personal_assets</code>, workspace DBs</td><td style="text-align:left;">Sum of liquidity, investments, personal goods, and workspace equity</td><td style="text-align:left;">Overall market net capitalization of maker</td></tr><tr><td style="text-align:left;"><strong>&quot;Accounts (Cash)&quot;</strong></td><td style="text-align:left;"><code>personal_accounts</code></td><td style="text-align:left;">Aggregate balance of active accounts translated to base currency</td><td style="text-align:left;">Readily spendable liquidity and cash reserves</td></tr><tr><td style="text-align:left;"><strong>&quot;Investments&quot;</strong></td><td style="text-align:left;"><code>personal_assets</code> (<code>asset_kind = &#39;investment&#39;</code>)</td><td style="text-align:left;">Real-time market valuation of active portfolio positions</td><td style="text-align:left;">Capital deployed in securities, crypto, and loans</td></tr><tr><td style="text-align:left;"><strong>&quot;Personal Assets&quot;</strong></td><td style="text-align:left;"><code>personal_assets</code> (<code>asset_kind = &#39;property&#39;</code>)</td><td style="text-align:left;">Appraised asset valuation × master&#39;s ownership percentage</td><td style="text-align:left;">Real estate, vehicles, and tangible assets</td></tr><tr><td style="text-align:left;"><strong>&quot;Workspace Property&quot;</strong></td><td style="text-align:left;"><code>transactions</code>, <code>materials</code>, <code>products</code>, <code>assets</code> in workspaces</td><td style="text-align:left;">Cash register + raw materials (MAC) + finished goods (FIFO) + depreciated tools</td><td style="text-align:left;">Operating manufacturing assets of business</td></tr><tr><td style="text-align:left;"><strong>&quot;Earned in businesses&quot;</strong></td><td style="text-align:left;"><code>sales_log</code>, <code>transactions</code>, <code>assets</code> in workspaces</td><td style="text-align:left;">Revenue − cost of goods sold − operational overhead − tool depreciation</td><td style="text-align:left;">Operational net profit across workshops</td></tr><tr><td style="text-align:left;"><strong>&quot;Outside income&quot;</strong></td><td style="text-align:left;"><code>personal_transactions</code> (<code>type = &#39;income&#39;</code>)</td><td style="text-align:left;">Sum of all logged external non-workshop earnings</td><td style="text-align:left;">Earnings generated outside core workshops</td></tr><tr><td style="text-align:left;"><strong>&quot;Investment Profit&quot;</strong></td><td style="text-align:left;"><code>personal_assets</code></td><td style="text-align:left;">Unrealized appreciation on active holdings + realized profit on closed deals</td><td style="text-align:left;">Aggregate investment portfolio performance</td></tr><tr><td style="text-align:left;"><strong>&quot;Living expenses&quot;</strong></td><td style="text-align:left;">Balance delta formula</td><td style="text-align:left;">Total earning pool − (major outflows + net worth delta)</td><td style="text-align:left;">Discretionary domestic living expenditure</td></tr></tbody></table><hr><h2 id="action-controls-and-toolbar" tabindex="-1">Action Controls and Toolbar <a class="header-anchor" href="#action-controls-and-toolbar" aria-label="Permalink to &quot;Action Controls and Toolbar&quot;">​</a></h2><p>The upper-right section of the dashboard features rapid maintenance tools:</p><ul><li><strong>&quot;Refresh summary data&quot;:</strong> forces an immediate multi-workspace database rescanning cycle and recalculates currency balances without requiring an application restart;</li><li><strong>Documentation Shortcut <code>[?]</code>:</strong> opens this user manual in your browser;</li><li><strong>Empty State Onboarding:</strong> when launching a fresh installation, the screen displays a welcome card prompting you to register your initial account or activate <strong>&quot;Demo Mode&quot;</strong> to explore pre-filled sample data.</li></ul><div class="tip custom-block"><p class="custom-block-title">Craftsman&#39;s Advice: Overcoming the Cash Flow Mirage</p><p>Never gauge workshop prosperity strictly by the cash on your bank card. If cash reserves dipped by $2,000 this month while warehouse shelves took in $2,500 of premium leather and the workbench completed $1,500 in finished goods, your business experienced no decline — its net equity expanded. The Capital Dashboard reveals this true growth under &quot;Workspace Property&quot;.</p></div><div class="warning custom-block"><p class="custom-block-title">Preventing Asset Duplication</p><p>Maintain clean ownership allocations in the &quot;Property &amp; Resources&quot; tab. If machinery worth $5,000 is recorded simultaneously as a 100% personal asset and 100% workshop equipment, the engine will double-count the item, inflating your net worth by $5,000. Run the collision audit tool periodically to ensure ledger purity.</p></div><hr><h2 id="troubleshooting-common-pitfalls" tabindex="-1">Troubleshooting &amp; Common Pitfalls <a class="header-anchor" href="#troubleshooting-common-pitfalls" aria-label="Permalink to &quot;Troubleshooting &amp; Common Pitfalls&quot;">​</a></h2><div class="faq-grid"><details class="faq-item"><summary class="faq-summary">What should I do if summary figures diverge from active workshop balances?</summary><div class="faq-content"><p>Click the &quot;Refresh summary data&quot; button (sync icon) in the upper right toolbar. The system rescans all physical workspace SQLite database files in the background, recalculates warehouse moving average costs, and updates headline totals.</p></div></details><details class="faq-item"><summary class="faq-summary">Why does the &quot;Discretionary Spending&quot; metric show a negative value?</summary><div class="faq-content"><p>A negative discretionary spending calculation indicates that net asset expansion outpaced recognized income inflows. Review the &quot;Major Transactions&quot; journal: an external capital inflow (such as off-platform freelance income, asset liquidation, or a loan repayment) was likely omitted from the record.</p></div></details><details class="faq-item"><summary class="faq-summary">How do I fix asset valuation duplication between workshop and personal portfolios?</summary><div class="faq-content"><p>Open the &quot;Property &amp; Resources&quot; sub-tab and click the &quot;Collision Audit&quot; button. Calibrate ownership share distribution so the combined allocation across Personal, Production, and Services strictly sums to 100%.</p></div></details></div>',54))])}const q=s(p,[["render",h]]);export{w as __pageData,q as default};
